# Surah At-Tawbah (chapter 9) — part 2: ayat 11-20 (IDs 1246-1255)
SURAH = 9

ENTRIES = {
1246: (
"پس — اگر — وہ — توبہ کریں — اور نماز قائم کریں — اور زکوٰۃ دیں — تو — تمہارے — دینی بھائی ہیں — اور ہم — آیات — ان لوگوں کے لیے — تفصیل سے بیان کر رہے ہیں — جو جانتے ہیں",
"""۱۔ توبہ — مؤمن بھائی بنا دیتی ہے۔
۲۔ ’’فَإِن تَابُوا وَأَقَامُوا الصَّلَاۃَ وَآتَوُا الزَّكَاۃَ فَإِخْوَانُكُمْ فِي الدِّينِ وَنُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَعْلَمُونَ‘‘ — پس — اگر — وہ — توبہ کریں — اور نماز قائم کریں — اور زکوٰۃ دیں — تو — تمہارے — دینی بھائی ہیں — اور ہم — آیات — ان لوگوں کے لیے — تفصیل سے بیان کر رہے ہیں — جو جانتے ہیں — یعنی توبہ — نماز اور زکوٰۃ — کو — دین کا معیار بناتی ہے — اور — توبہ کرنے والے — دینی بھائی بن جاتے ہیں۔
۳۔ عملی سبق: توبہ — آپ کو برادری میں — شامل — کر دیتی ہے۔"""
),
1247: (
"اور — اگر — وہ — اپنے عہد کے بعد — اپنی قسمیں — توڑ دیں — اور — تمہارے دین پر — طعن کریں — تو کفر کے — پیشواؤں سے — لڑو — بے شک — ان — کی کوئی — قسم — نہیں — شاید — وہ — باز آ جائیں",
"""۱۔ عہد توڑنے والے — آئمہ کفر۔
۲۔ ’’وَإِن نَّكَثُوا أَيْمَانَهُم مِّن بَعْدِ عَهْدِهِمْ وَطَعَنُوا فِي دِينِكُمْ فَقَاتِلُوا أَئِمَّۃَ الْكُفْرِ إِنَّهُمْ لَا أَيْمَانَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ‘‘ — اور — اگر — وہ — اپنے عہد کے بعد — اپنی قسمیں — توڑ دیں — اور — تمہارے دین پر — طعن کریں — تو کفر کے — پیشواؤں سے — لڑو — بے شک — ان — کی کوئی — قسم — نہیں — شاید — وہ — باز آ جائیں — یعنی عہد توڑنے والے — آئمہ کفر بن جاتے ہیں — ان سے جنگ — جائز — ہے۔
۳۔ عملی سبق: عہد شکنی — سب سے بڑا جرم — ہے؛ رہنماؤں کے کفر کی سزا — جنگ — ہے۔"""
),
1248: (
"کیا — تم — ان — لوگوں سے — نہیں لڑوگے — جو — اپنی قسمیں توڑ دیں — اور — رسولؐ — کو — نکالنے کا — ارادہ کیا — اور — انہوں نے — تم سے — پہلے — شروع کیا — کیا — تم — ان سے — ڈرتے ہو — پس — اللہ — زیادہ — حقدار — ہے — کہ — تم — اس سے ڈرو — اگر — تم مؤمن ہو",
"""۱۔ مشرکین — پہلے — شروع کرنے والے — تھے۔
۲۔ ’’أَلَا تُقَاتِلُونَ قَوْمًا نَّكَثُوا أَيْمَانَهُمْ وَهَمُّوا بِإِخْرَاجِ الرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّۃٍ أَتَخْشَوْنَهُمْ فَاللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ‘‘ — کیا — تم — ان — لوگوں سے — نہیں لڑوگے — جو — اپنی قسمیں توڑ دیں — اور — رسولؐ — کو — نکالنے کا — ارادہ کیا — اور — انہوں نے — تم سے — پہلے — شروع کیا — کیا — تم — ان سے — ڈرتے ہو — پس — اللہ — زیادہ — حقدار — ہے — کہ — تم — اس سے ڈرو — اگر — تم مؤمن ہو — یعنی مشرکین — عہد توڑنے والے — اور ہجرت کا سبب — بنے؛ ڈر — صرف اللہ کا ہونا چاہیے۔
۳۔ عملی سبق: مؤمن — صرف اللہ سے — ڈرتا ہے؛ کسی سے نہیں۔"""
),
1249: (
"ان سے — لڑو — اللہ — انہیں — تمہارے ہاتھوں — عذاب دے گا — اور — انہیں — ذلیل کرے گا — اور — تمہیں — ان پر — غالب کرے گا — اور — مؤمن قوم — کے سینوں — کو شفاء دے گا",
"""۱۔ جہاد — اللہ کی طرف سے — عذاب اور فتح۔
۲۔ ’’قَاتِلُوهُمْ يُعَذِّبْهُمُ اللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ‘‘ — ان سے — لڑو — اللہ — انہیں — تمہارے ہاتھوں — عذاب دے گا — اور — انہیں — ذلیل کرے گا — اور — تمہیں — ان پر — غالب کرے گا — اور — مؤمن قوم — کے سینوں — کو شفاء دے گا — یعنی جہاد — اللہ کی طرف سے — کافروں کا عذاب — اور مؤمنوں کی تسلی — کا ذریعہ ہے۔
۳۔ عملی سبق: جہاد — اللہ کی طرف سے — فتح اور شفاء ہے۔"""
),
1250: (
"اور — ان کے دلوں — کی غصہ — کو دور کر دے گا — اور — اللہ — جس کی چاہے — توبہ — قبول کرتا ہے — اور — اللہ — جاننے والا حکمت والا ہے",
"""۱۔ جہاد — دل کی شفاء اور اللہ کی رحمت کا ذریعہ۔
۲۔ ’’وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ اللَّهُ عَلَىٰ مَن يَشَاءُ وَاللَّهُ عَلِيمٌ حَكِيمٌ‘‘ — اور — ان کے دلوں — کی غصہ — کو دور کر دے گا — اور — اللہ — جس کی چاہے — توبہ — قبول کرتا ہے — اور — اللہ — جاننے والا حکمت والا ہے — یعنی جہاد — مؤمنوں کے دلوں کو — سکون دیتا ہے — اور اللہ — کسی کی بھی توبہ — قبول کر سکتا ہے۔
۳۔ عملی سبق: دل کی شفاء — اللہ کے ہاتھ میں ہے۔"""
),
1251: (
"کیا — تم نے — یہ گمان کیا کہ — تم — چھوڑ دیے جاؤ گے — حالانکہ — اللہ — نے — ابھی — تک — انہیں — ظاہر نہیں کیا — جنہوں نے — تم میں سے — جہاد کیا — اور — اللہ کے علاوہ — کسی — کو — والی — نہ بنایا — اور — نہ — اس کے رسولؐ — کو — اور — نہ — مؤمنوں — کو — اور — اللہ — تمہارے اعمال — سے — باخبر ہے",
"""۱۔ جہاد — مؤمنوں کی پہچان — اور جانچ۔
۲۔ ’’أَمْ حَسِبْتُمْ أَن تُتْرَكُوا وَلَمَّا يَعْلَمِ اللَّهُ الَّذِينَ جَاهَدُوا مِنكُمْ وَلَمْ يَتَّخِذُوا مِن دُونِ اللَّهِ وَلَا رَسُولِهِ وَلَا الْمُؤْمِنِينَ وَلِيجَۃً وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ‘‘ — کیا — تم نے — یہ گمان کیا کہ — تم — چھوڑ دیے جاؤ گے — حالانکہ — اللہ — نے — ابھی — تک — انہیں — ظاہر نہیں کیا — جنہوں نے — تم میں سے — جہاد کیا — اور — اللہ کے علاوہ — کسی — کو — والی — نہ بنایا — اور — نہ — اس کے رسولؐ — کو — اور — نہ — مؤمنوں — کو — اور — اللہ — تمہارے اعمال — سے — باخبر ہے — یعنی جہاد — اور — وفاداری — دونوں — جانچ کے معیار ہیں؛ اللہ سب جانتا ہے۔
۳۔ عملی سبق: جہاد اور وفاداری — مؤمنوں کا طرزِ زندگی ہے۔"""
),
1252: (
"مشرکوں — کے لیے — لائق نہیں — کہ وہ — اللہ کی مساجد کو — آباد کریں — خود اپنے اوپر — کفر — کی گواہی دیتے ہوئے — یہ — وہ لوگ ہیں — جن کے اعمال — ضائع ہو گئے — اور وہ — جہنم میں — ہمیشہ رہیں گے",
"""۱۔ مشرک — مسجد کے نگینہ دار نہیں ہو سکتے۔
۲۔ ’’مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا مَسَاجِدَ اللَّهِ شَاهِدِينَ عَلَىٰ أَنفُسِهِم بِالْكُفْرِ أُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ وَفِي النَّارِ هُمْ خَالِدُونَ‘‘ — مشرکوں — کے لیے — لائق نہیں — کہ وہ — اللہ کی مساجد کو — آباد کریں — خود اپنے اوپر — کفر — کی گواہی دیتے ہوئے — یہ — وہ لوگ ہیں — جن کے اعمال — ضائع ہو گئے — اور وہ — جہنم میں — ہمیشہ رہیں گے — یعنی مشرک — مسجد کا نگینہ نہیں بنا — سکتے — ان کے اعمال — ضائع ہیں۔
۳۔ عملی سبق: مسجد کا نگینہ — ایمان والوں کا حق ہے۔"""
),
1253: (
"مسجد کو — صرف — وہ — آباد کرتا ہے — جو — اللہ اور آخرت کے دن — پر ایمان رکھتا ہو — اور — نماز قائم کرتا ہو — اور زکوٰۃ دیتا ہو — اور — اللہ کے علاوہ — کسی سے — نہ ڈرے — پس — شاید — یہی لوگ — ہدایت یافتہ ہوں",
"""۱۔ مسجد کا نگینہ — ایمان، نماز، زکوٰۃ اور تقویٰ والے۔
۲۔ ’’إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَأَقَامَ الصَّلَاۃَ وَآتَى الزَّكَاۃَ وَلَمْ يَخْشَ إِلَّا اللَّهَ فَعَسَىٰ أُولَٰئِكَ أَن يَكُونُوا مِنَ الْمُهْتَدِينَ‘‘ — مسجد کو — صرف — وہ — آباد کرتا ہے — جو — اللہ اور آخرت کے دن — پر ایمان رکھتا ہو — اور — نماز قائم کرتا ہو — اور زکوٰۃ دیتا ہو — اور — اللہ کے علاوہ — کسی سے — نہ ڈرے — پس — شاید — یہی لوگ — ہدایت یافتہ ہوں — یعنی مسجد کا نگینہ — وہ — مؤمن بنا سکتا ہے — جو — ایمان، نماز، زکوٰۃ اور — اللہ کے خوف سے — مالا مال ہو۔
۳۔ عملی سبق: مسجد کو آباد کرنے والے — ہدایت یافتہ — ہیں۔"""
),
1254: (
"کیا — تم — حاجیوں کو پانی پلانا — اور — مسجد الحرام کی نگہداشت کو — اس — کے برابر سمجھتے ہو — جو — اللہ اور آخرت کے دن — پر ایمان لایا — اور — اللہ کی راہ میں — جہاد کیا — وہ — اللہ — کے نزدیک — برابر نہیں — اور — اللہ — ظالموں کو — ہدایت نہیں دیتا",
"""۱۔ جہاد — پانی پلانے سے — بڑھ کر ہے۔
۲۔ ’’أَجَعَلْتُمْ سِقَايَۃَ الْحَاجِّ وَعِمَارَۃَ الْمَسْجِدِ الْحَرَامِ كَمَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَجَاهَدَ فِي سَبِيلِ اللَّهِ لَا يَسْتَوُونَ عِندَ اللَّهِ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ‘‘ — کیا — تم — حاجیوں کو پانی پلانا — اور — مسجد الحرام کی نگہداشت کو — اس — کے برابر سمجھتے ہو — جو — اللہ اور آخرت کے دن — پر ایمان لایا — اور — اللہ کی راہ میں — جہاد کیا — وہ — اللہ — کے نزدیک — برابر نہیں — اور — اللہ — ظالموں کو — ہدایت نہیں دیتا — یعنی ایمان اور جہاد — سقاۃ الحاج اور عمارت مسجد الحرام سے — بہتر — ہیں۔
۳۔ عملی سبق: ایمان اور جہاد — سب سے بڑی عبادت ہے۔"""
),
1255: (
"وہ — لوگ — جنہوں نے ایمان لایا — ہجرت کی — اور — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد کیا — اللہ کے نزدیک — سب سے بلند درجے والے ہیں — اور — یہی لوگ — کامیاب ہیں",
"""۱۔ ایمان + ہجرت + جہاد = سب سے بلند درجے۔
۲۔ ’’الَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ بِأَمْوَالِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَۃً عِندَ اللَّهِ وَأُولَٰئِكَ هُمُ الْفَائِزُونَ‘‘ — وہ — لوگ — جنہوں نے ایمان لایا — ہجرت کی — اور — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد کیا — اللہ کے نزدیک — سب سے بلند درجے والے ہیں — اور — یہی لوگ — کامیاب ہیں — یعنی ایمان، ہجرت اور جہاد — سب سے بلند درجے — اور کامیابی — کا معیار ہیں۔
۳۔ عملی سبق: ایمان، ہجرت اور جہاد — کامیابی کا راز ہے۔"""
),
}
